import re
import string


class LongestWord:

    def __init__(self):
        self._word_list = []

    def add_word(self, word):
        self._word_list.append(word)

    def _is_punctuation(self):
        return re.escape(string.punctuation)

    def _clean_sentence(self, sentence):
        cleaned = sentence.lower()
        cleaned = re.sub('[%s]' % self._is_punctuation(), '', cleaned)
        return re.split(' ', cleaned)

    def _is_in_word_list(self, word):
        return word in self._word_list

    def _is_longer(self, word, current_longest):
        return len(word) > len(current_longest)

    def find_longest_word(self, sentence):
        longest_word = ""
        words = self._clean_sentence(sentence)
        for word in words:
            if self._is_in_word_list(word) and self._is_longer(word, longest_word):
                longest_word = word
        return longest_word
